#include <string.h>

int handle_far_return(struct x86_emulate_ctxt *ctxt) {
    void *eip = NULL;
    void *cs = NULL;
    int status;

    // Retrieve instruction pointer (EIP) from the stack
    status = emulate_pop(ctxt, &eip);
    if (status != X86EMUL_CONTINUE) {
        return status;
    }

    // Retrieve code segment (CS) from the stack
    status = emulate_pop(ctxt, &cs);
    if (status != X86EMUL_CONTINUE) {
        return status;
    }

    // Check for privilege level violations
    if (ctxt->current_privilege_level > ctxt->target_privilege_level) {
        return X86EMUL_PRIVILEGE;
    }

    // Load the segment descriptor for the code segment
    status = load_segment_descriptor(ctxt, cs);
    if (status != X86EMUL_CONTINUE) {
        return status;
    }

    // Assign the new instruction pointer
    ctxt->eip = eip;

    return X86EMUL_CONTINUE;
}
